class TransactionOperation:
    def __init__(self, query, params, operation_type, table, expected_rows=1):
        self.query = query
        self.params = params
        self.operation_type = operation_type
        self.table = table
        self.expected_rows = expected_rows

class TransactionResult:
    def __init__(self, success, error_message=None):
        self.success = success
        self.error_message = error_message

class TransactionManager:
    def __init__(self, db_manager):
        self.db_manager = db_manager

    def execute_atomic_operations(self, operations: List[TransactionOperation]) -> TransactionResult:
        try:
            with self.db_manager._get_connection() as conn:
                cursor = conn.cursor()
                for op in operations:
                    cursor.execute(op.query, op.params)
                conn.commit()
                return TransactionResult(True)
        except Exception as e:
            return TransactionResult(False, str(e))

