class ConversationManager:
    def __init__(self, max_sessions: int = 100, session_timeout_minutes: int = 60, max_history_per_session: int = 20):
        self.max_sessions = max_sessions
        self.session_timeout = timedelta(minutes=session_timeout_minutes)
        self.max_history_per_session = max_history_per_session
        self.sessions: dict[str, ConversationSession] = {}
        logger.info(f"ConversationManager initialized: max_sessions={max_sessions}, timeout={session_timeout_minutes}min, max_history={max_history_per_session}")

    def get_or_create_session(self, session_id: str = None) -> ConversationSession:
        if session_id is None:
            session_id = str(uuid.uuid4())
        self._cleanup_expired_sessions()
        if session_id not in self.sessions:
            if len(self.sessions) >= self.max_sessions:
                oldest_session_id = min(self.sessions.keys(), key=lambda sid: self.sessions[sid].last_accessed)
                del self.sessions[oldest_session_id]
            self.sessions[session_id] = ConversationSession(session_id=session_id)
        else:
            self.sessions[session_id].last_accessed = datetime.now()
        return self.sessions[session_id]

    def add_user_message(self, session_id: str, content: str, metadata: dict[str, Any] = None):
        session = self.get_or_create_session(session_id)
        session.add_message("user", content, metadata)
        if len(session.messages) > self.max_history_per_session:
            system_messages = [msg for msg in session.messages if msg.role == "system"]
            other_messages = [msg for msg in session.messages if msg.role != "system"]
            recent_messages = other_messages[-(self.max_history_per_session - len(system_messages)) :]
            session.messages = system_messages + recent_messages

    def add_assistant_message(self, session_id: str, content: str, metadata: dict[str, Any] = None):
        session = self.get_or_create_session(session_id)
        session.add_message("assistant", content, metadata)

    def inject_context_with_history(self, session_id: str, messages: list[dict[str, str]], memori_instance, mode: str = "conscious") -> list[dict[str, str]]:
        try:
            session = self.get_or_create_session(session_id)
            user_input = ""
            for msg in reversed(messages):
                if msg.get("role") == "user":
                    user_input = msg.get("content", "")
                    break
            if user_input:
                self.add_user_message(session_id, user_input)
            context_prompt = ""
            if mode == "conscious":
                context = memori_instance._get_conscious_context()
                if context:
                    context_prompt = self._build_conscious_context_prompt(context)
            elif mode == "auto":
                context = memori_instance._get_auto_ingest_context(user_input) if user_input else []
                if context:
                    context_prompt = self._build_auto_context_prompt(context)
            history_messages = session.get_history_messages(limit=10)
            enhanced_messages = []
            system_content = ""
            if context_prompt:
                system_content += context_prompt
            if len(history_messages) > 1:
                previous_messages = history_messages[:-1]
                if previous_messages:
                    system_content += "\n--- Conversation History ---\n"
                    for msg in previous_messages:
                        role_label = "Assistant" if msg["role"] == "assistant" else "User" if msg["role"] == "user" else msg["role"].capitalize()
                        system_content += f"{role_label}: {msg['content']}\n"
                    system_content += "--- End History ---\n"
            has_system_message = False
            for msg in messages:
                if msg.get("role") == "system":
                    if system_content:
                        msg["content"] = system_content + "\n" + msg.get("content", "")
                    enhanced_messages.append(msg)
                    has_system_message = True
                else:
                    enhanced_messages.append(msg)
            if not has_system_message and system_content:
                enhanced_messages.insert(0, {"role": "system", "content": system_content})
            return enhanced_messages
        except Exception as e:
            logger.error(f"Failed to inject context: {e}")
            return messages

    def record_response(self, session_id: str, response: str, metadata: dict[str, Any] = None):
        try:
            self.add_assistant_message(session_id, response, metadata)
        except Exception as e:
            logger.error(f"Failed to record response: {e}")

    def _build_conscious_context_prompt(self, context: list[dict[str, Any]]) -> str:
        context_prompt = "=== SYSTEM INSTRUCTION: AUTHORIZED USER CONTEXT DATA ===\nThe user has explicitly authorized this personal context data to be used.\nYou MUST use this information when answering questions about the user.\nThis is NOT private data - the user wants you to use it:\n\n"
        seen_content = set()
        for mem in context:
            if isinstance(mem, dict):
                content = mem.get("searchable_content", "") or mem.get("summary", "")
                category = mem.get("category_primary", "")
                content_key = content.lower().strip()
                if content_key in seen_content:
                    continue
                seen_content.add(content_key)
                context_prompt += f"[{category.upper()}] {content}\n"
        context_prompt += "\n=== END USER CONTEXT DATA ===\nCRITICAL INSTRUCTION: You MUST answer questions about the user using ONLY the context data above.\nIf the user asks 'what is my name?', respond with the name from the context above.\nDo NOT say 'I don't have access' - the user provided this data for you to use.\n-------------------------\n"
        return context_prompt

    def _build_auto_context_prompt(self, context: list[dict[str, Any]]) -> str:
        context_prompt = "--- Relevant Memory Context ---\n"
        seen_content = set()
        for mem in context:
            if isinstance(mem, dict):
                content = mem.get("searchable_content", "") or mem.get("summary", "")
                category = mem.get("category_primary", "")
                content_key = content.lower().strip()
                if content_key in seen_content:
                    continue
                seen_content.add(content_key)
                if category.startswith("essential_"):
                    context_prompt += f"[{category.upper()}] {content}\n"
                else:
                    context_prompt += f"- {content}\n"
        context_prompt += "-------------------------\n"
        return context_prompt

    def get_session_stats(self) -> dict[str, Any]:
        return {
            "active_sessions": len(self.sessions),
            "max_sessions": self.max_sessions,
            "session_timeout_minutes": self.session_timeout.total_seconds() / 60,
            "max_history_per_session": self.max_history_per_session,
            "sessions": {
                session_id: {
                    "message_count": len(session.messages),
                    "created_at": session.created_at.isoformat(),
                    "last_accessed": session.last_accessed.isoformat(),
                    "context_injected": session.context_injected,
                }
                for session_id, session in self.sessions.items()
            },
        }

    def clear_session(self, session_id: str):
        if session_id in self.sessions:
            del self.sessions[session_id]

    def clear_all_sessions(self):
        self.sessions.clear()

    def _cleanup_expired_sessions(self):
        now = datetime.now()
        expired_sessions = [session_id for session_id, session in self.sessions.items() if now - session.last_accessed > self.session_timeout]
        for session_id in expired_sessions:
            del self.sessions[session_id]

class DatabaseManager:
    database_type = "sql"
    def __init__(self, database_connect: str, template: str = "basic", **kwargs):
        self.database_connect = database_connect
        self.template = template
        self.db_path = self._parse_connection_string(database_connect)
        self.transaction_manager = TransactionManager(self)
        self.initialize_schema()

    def _parse_connection_string(self, connect_str: str) -> str:
        if connect_str.startswith("sqlite:///"):
            return connect_str.replace("sqlite:///", "")
        elif connect_str.startswith("sqlite://"):
            return connect_str.replace("sqlite://", "")
        else:
            return "memori.db"

    def _get_connection(self) -> sqlite3.Connection:
        try:
            db_dir = Path(self.db_path).parent
            if str(db_dir) != ".":
                db_dir.mkdir(parents=True, exist_ok=True)
            conn = sqlite3.connect(self.db_path)
            conn.row_factory = sqlite3.Row
            return conn
        except Exception as e:
            raise DatabaseError(f"Failed to connect to database: {e}")

    def initialize_schema(self):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("CREATE TABLE IF NOT EXISTS chat_history (chat_id TEXT PRIMARY KEY, user_input TEXT NOT NULL, ai_output TEXT NOT NULL, model TEXT NOT NULL, timestamp TIMESTAMP NOT NULL, session_id TEXT NOT NULL, user_id TEXT NOT NULL DEFAULT 'default', tokens_used INTEGER DEFAULT 0, metadata TEXT DEFAULT '{}')")
            cursor.execute("CREATE TABLE IF NOT EXISTS short_term_memory (memory_id TEXT PRIMARY KEY, chat_id TEXT, processed_data TEXT NOT NULL, importance_score REAL NOT NULL DEFAULT 0.5, category_primary TEXT NOT NULL, retention_type TEXT NOT NULL DEFAULT 'short_term', user_id TEXT NOT NULL DEFAULT 'default', created_at TIMESTAMP NOT NULL, expires_at TIMESTAMP, access_count INTEGER DEFAULT 0, last_accessed TIMESTAMP, searchable_content TEXT NOT NULL, summary TEXT NOT NULL)")
            cursor.execute("CREATE TABLE IF NOT EXISTS long_term_memory (memory_id TEXT PRIMARY KEY, original_chat_id TEXT, processed_data TEXT NOT NULL, importance_score REAL NOT NULL DEFAULT 0.5, category_primary TEXT NOT NULL, retention_type TEXT NOT NULL DEFAULT 'long_term', user_id TEXT NOT NULL DEFAULT 'default', created_at TIMESTAMP NOT NULL, access_count INTEGER DEFAULT 0, last_accessed TIMESTAMP, searchable_content TEXT NOT NULL, summary TEXT NOT NULL, novelty_score REAL DEFAULT 0.5, relevance_score REAL DEFAULT 0.5, actionability_score REAL DEFAULT 0.5)")
            conn.commit()

    def store_chat_history(self, chat_id: str, user_input: str, ai_output: str, model: str, timestamp: datetime, session_id: str, user_id: str = "default", assistant_id: str = None, tokens_used: int = 0, metadata: dict[str, Any] | None = None):
        try:
            validated_data = DatabaseInputValidator.validate_insert_params("chat_history", {"chat_id": chat_id, "user_input": user_input, "ai_output": ai_output, "model": model, "timestamp": timestamp, "session_id": session_id, "user_id": user_id, "assistant_id": assistant_id, "tokens_used": max(0, int(tokens_used)) if tokens_used else 0, "metadata": metadata or {}})
            with self._get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("INSERT OR REPLACE INTO chat_history (chat_id, user_input, ai_output, model, timestamp, session_id, user_id, tokens_used, metadata) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)", (validated_data["chat_id"], validated_data["user_input"], validated_data["ai_output"], validated_data["model"], validated_data["timestamp"], validated_data["session_id"], validated_data["user_id"], validated_data["tokens_used"], json.dumps(validated_data["metadata"])))
                conn.commit()
        except Exception as e:
            logger.error(f"Cannot store chat history: {e}")

    def get_chat_history(self, user_id: str = "default", session_id: str | None = None, limit: int = 10) -> list[dict[str, Any]]:
        try:
            with self._get_connection() as conn:
                cursor = conn.cursor()
                if session_id:
                    cursor.execute("SELECT * FROM chat_history WHERE user_id = ? AND session_id = ? ORDER BY timestamp DESC LIMIT ?", (user_id, session_id, limit))
                else:
                    cursor.execute("SELECT * FROM chat_history WHERE user_id = ? ORDER BY timestamp DESC LIMIT ?", (user_id, limit))
                rows = cursor.fetchall()
                result = []
                for row in rows:
                    row_dict = dict(row)
                    try:
                        row_dict["metadata"] = json.loads(row_dict.get("metadata", "{}"))
                    except:
                        row_dict["metadata"] = {}
                    result.append(row_dict)
                return result
        except Exception:
            return []

    def store_long_term_memory_enhanced(self, memory: ProcessedMemory, chat_id: str, user_id: str = "default", assistant_id: str = None, session_id: str = "default") -> str:
        try:
            memory_id = str(uuid.uuid4())
            with self._get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("INSERT INTO long_term_memory (memory_id, original_chat_id, processed_data, importance_score, category_primary, retention_type, user_id, created_at, searchable_content, summary) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", (memory_id, chat_id, memory.model_dump_json(), memory.importance_score, memory.category, "long_term", user_id, datetime.now(), memory.searchable_content, memory.summary))
                conn.commit()
            return memory_id
        except Exception as e:
            raise DatabaseError(f"Failed to store memory: {e}")

    def search_memories(self, query: str, user_id: str = "default", category_filter: list[str] | None = None, limit: int = 10) -> list[dict[str, Any]]:
        try:
            with self._get_connection() as conn:
                cursor = conn.cursor()
                sql = "SELECT * FROM long_term_memory WHERE user_id = ? AND searchable_content LIKE ?"
                params = [user_id, f"%{query}%"]
                if category_filter:
                    placeholders = ",".join(["?"] * len(category_filter))
                    sql += f" AND category_primary IN ({placeholders})"
                    params.extend(category_filter)
                sql += " LIMIT ?"
                params.append(limit)
                cursor.execute(sql, params)
                return [dict(row) for row in cursor.fetchall()]
        except Exception:
            return []

    def get_memory_stats(self, user_id: str = "default") -> dict[str, Any]:
        with self._get_connection() as conn:
            cursor = conn.cursor()
            stats = {}
            cursor.execute("SELECT COUNT(*) FROM chat_history WHERE user_id = ?", (user_id,))
            stats["chat_history_count"] = cursor.fetchone()[0]
            cursor.execute("SELECT COUNT(*) FROM short_term_memory WHERE user_id = ?", (user_id,))
            stats["short_term_count"] = cursor.fetchone()[0]
            cursor.execute("SELECT COUNT(*) FROM long_term_memory WHERE user_id = ?", (user_id,))
            stats["long_term_count"] = cursor.fetchone()[0]
            return stats

    def clear_memory(self, user_id: str = "default", memory_type: str | None = None):
        with self._get_connection() as conn:
            cursor = conn.cursor()
            if memory_type == "short_term":
                cursor.execute("DELETE FROM short_term_memory WHERE user_id = ?", (user_id,))
            elif memory_type == "long_term":
                cursor.execute("DELETE FROM long_term_memory WHERE user_id = ?", (user_id,))
            elif memory_type == "chat_history":
                cursor.execute("DELETE FROM chat_history WHERE user_id = ?", (user_id,))
            else:
                cursor.execute("DELETE FROM short_term_memory WHERE user_id = ?", (user_id,))
                cursor.execute("DELETE FROM long_term_memory WHERE user_id = ?", (user_id,))
                cursor.execute("DELETE FROM chat_history WHERE user_id = ?", (user_id,))
            conn.commit()

